import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Page Triggers in AL","description":"","frontmatter":{},"headers":[],"relativePath":"pages-and-user-interfaces/page-triggers.md","filePath":"pages-and-user-interfaces/page-triggers.md"}`),a={name:`pages-and-user-interfaces/page-triggers.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="page-triggers-in-al" tabindex="-1">Page Triggers in AL <a class="header-anchor" href="#page-triggers-in-al" aria-label="Permalink to “Page Triggers in AL”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>In Business Central, <strong>Page Triggers</strong> are predefined execution points that allow developers to execute AL code in response to specific events occurring within a page.</p><p>For example, imagine we have a Product Card page.</p><p>We might want to:</p><ul><li>Display a welcome message when the page opens.</li><li>Perform calculations when a record is retrieved.</li><li>Initialize default values when a new product is created.</li><li>Validate information when a user changes a field.</li><li>Execute custom logic when a user closes the page.</li></ul><p>Instead of manually calling these operations, we use page triggers to execute code automatically when the corresponding events occur.</p><p><strong>Key idea:</strong> Page triggers allow us to control how a page behaves during its lifecycle and when users interact with it.</p><h2 id="declaring-page-triggers" tabindex="-1">Declaring Page Triggers <a class="header-anchor" href="#declaring-page-triggers" aria-label="Permalink to “Declaring Page Triggers”">​</a></h2><p>Page triggers are declared inside the page object using the <code>trigger</code> keyword.</p><p><strong>General syntax:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trigger TriggerName()</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    // AL statements</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50100 ProductCard</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = Card;</span></span>
<span class="line"><span>    SourceTable = Product;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    trigger OnOpenPage()</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        Message(&#39;Welcome to the Product Card!&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here, <code>OnOpenPage()</code> executes when the page is opened.</p><p>Notice that we don&#39;t manually call the trigger. Business Central invokes it automatically when the corresponding event occurs.</p><h2 id="common-page-triggers" tabindex="-1">Common Page Triggers <a class="header-anchor" href="#common-page-triggers" aria-label="Permalink to “Common Page Triggers”">​</a></h2><p>Let&#39;s explore the important page triggers you&#39;ll encounter when developing Business Central extensions.</p><h3 id="oninit" tabindex="-1">OnInit <a class="header-anchor" href="#oninit" aria-label="Permalink to “OnInit”">​</a></h3><p>The <code>OnInit</code> trigger executes when the page is initialized, immediately after its variables have been cleared and the page is loaded.</p><p>It is commonly used to initialize page variables and configure properties.</p><p><strong>Example:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trigger OnInit()</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    Message(&#39;Initializing Product Card...&#39;);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p><strong>When to use it:</strong> When you need to initialize variables or configure dynamic properties during page initialization.</p><p><strong>Important:</strong> At this stage, the page controls haven&#39;t been instantiated. Therefore, you cannot interact with controls or call control add-in methods from this trigger.</p><h3 id="onopenpage" tabindex="-1">OnOpenPage <a class="header-anchor" href="#onopenpage" aria-label="Permalink to “OnOpenPage”">​</a></h3><p>The <code>OnOpenPage</code> trigger executes after the page has been initialized and run.</p><p>It is useful when you need to perform operations as the page opens.</p><p><strong>Example:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trigger OnOpenPage()</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    Message(&#39;Product Card opened successfully!&#39;);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p><strong>When to use it:</strong></p><ul><li>Initializing page-specific behavior.</li><li>Applying filters.</li><li>Configuring dynamic properties.</li><li>Performing initialization logic when the page opens.</li></ul><p>One particularly important use is dynamically controlling the <code>Visible</code> property of page columns.</p><p><strong>Important:</strong> If an error occurs in this trigger, the page closes.</p><h3 id="onclosepage" tabindex="-1">OnClosePage <a class="header-anchor" href="#onclosepage" aria-label="Permalink to “OnClosePage”">​</a></h3><p>The <code>OnClosePage</code> trigger executes when a page closes, after the <code>OnQueryClosePage</code> trigger has been executed.</p><p><strong>Example:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trigger OnClosePage()</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    Message(&#39;Product Card closed.&#39;);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p><strong>When to use it:</strong> When you need to execute cleanup or other logic as a page closes.</p><p><strong>Important:</strong> This trigger is only invoked when the page is hosted in a modal popup window (MPO). Don&#39;t assume it executes whenever any page closes.</p><h3 id="onqueryclosepage" tabindex="-1">OnQueryClosePage <a class="header-anchor" href="#onqueryclosepage" aria-label="Permalink to “OnQueryClosePage”">​</a></h3><p>The <code>OnQueryClosePage</code> trigger executes when Business Central is about to close a page.</p><p>Unlike <code>OnClosePage</code>, this trigger allows you to control whether the page should be closed.</p><p><strong>Example:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trigger OnQueryClosePage(CloseAction: Action): Boolean</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    exit(Confirm(&#39;Are you sure you want to close this page?&#39;));</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Here:</p><ul><li><code>Confirm()</code> asks the user to confirm the operation.</li><li><code>exit()</code> returns the result of the confirmation.</li><li>If the user selects Yes, the page can close.</li><li>If the user selects No, the page remains open.</li></ul><p><strong>When to use it:</strong> When you need to perform checks or obtain confirmation before allowing a page to close.</p><h3 id="onaftergetrecord" tabindex="-1">OnAfterGetRecord <a class="header-anchor" href="#onaftergetrecord" aria-label="Permalink to “OnAfterGetRecord”">​</a></h3><p>The <code>OnAfterGetRecord</code> trigger executes after a record has been retrieved from the source table but before it is displayed to the user.</p><p>It is particularly useful when working with calculated values that depend on the current record.</p><p><strong>Example:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trigger OnAfterGetRecord()</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    Message(&#39;Retrieved product: %1&#39;, Rec.Name);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p><strong>When to use it:</strong> When you need to calculate or initialize values based on the record currently being retrieved.</p><p><strong>Important distinction:</strong> This trigger is not limited to the record currently selected by the user.</p><p>For example, on a List page, Business Central can retrieve several records in batches. Consequently, <code>OnAfterGetRecord</code> can execute for multiple records before the page is displayed.</p><p>This is particularly important when working with List pages.</p><h3 id="onaftergetcurrrecord" tabindex="-1">OnAfterGetCurrRecord <a class="header-anchor" href="#onaftergetcurrrecord" aria-label="Permalink to “OnAfterGetCurrRecord”">​</a></h3><p>The <code>OnAfterGetCurrRecord</code> trigger executes after Business Central retrieves the current record.</p><p>Unlike <code>OnAfterGetRecord</code>, this trigger specifically relates to the current record in the page.</p><p><strong>Example:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trigger OnAfterGetCurrRecord()</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    Message(&#39;Current product: %1&#39;, Rec.Name);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p><strong>When to use it:</strong> When you need to execute logic based on the currently selected record.</p><p>For example, you might want to update certain page variables whenever the user navigates between products.</p><p><strong>Remember:</strong></p><table tabindex="0"><thead><tr><th>Trigger</th><th>Purpose</th></tr></thead><tbody><tr><td><code>OnAfterGetRecord</code></td><td>Executes when a record is retrieved, before it is displayed.</td></tr><tr><td><code>OnAfterGetCurrRecord</code></td><td>Executes after the current record is retrieved.</td></tr></tbody></table><p>This distinction is especially important when working with List pages.</p><h3 id="onnewrecord" tabindex="-1">OnNewRecord <a class="header-anchor" href="#onnewrecord" aria-label="Permalink to “OnNewRecord”">​</a></h3><p>The <code>OnNewRecord</code> trigger executes after a new record has been initialized but before it is inserted into the table.</p><p>It is commonly used to assign default values to newly created records.</p><p><strong>Example:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trigger OnNewRecord(BelowxRec: Boolean)</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    Rec.&quot;Unit Price&quot; := 0;</span></span>
<span class="line"><span>    Rec.Inventory := 0;</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Here, whenever a user creates a new product through the page, the Unit Price and Inventory fields are initialized to zero.</p><p><strong>When to use it:</strong> When you need to initialize values or perform other operations before a new record is inserted.</p><h3 id="oninsertrecord" tabindex="-1">OnInsertRecord <a class="header-anchor" href="#oninsertrecord" aria-label="Permalink to “OnInsertRecord”">​</a></h3><p>The <code>OnInsertRecord</code> trigger executes before a new record is inserted into the table.</p><p>It allows you to perform additional checks before allowing the insertion.</p><p><strong>Example:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trigger OnInsertRecord(BelowxRec: Boolean): Boolean</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    if Rec.Name = &#39;&#39; then</span></span>
<span class="line"><span>        Error(&#39;Product name cannot be empty.&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    exit(true);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Here:</p><ul><li>Business Central checks whether the product name is empty.</li><li>If it is empty, <code>Error()</code> stops the insertion.</li><li>Otherwise, <code>exit(true)</code> allows the insertion to proceed.</li></ul><p>The Boolean return value determines whether the insertion is allowed:</p><table tabindex="0"><thead><tr><th>Return value</th><th>Meaning</th></tr></thead><tbody><tr><td><code>true</code></td><td>Allow the insertion.</td></tr><tr><td><code>false</code></td><td>Cancel the insertion.</td></tr></tbody></table><p><strong>When to use it:</strong> When you need to perform page-specific checks before a new record is inserted.</p><h3 id="onmodifyrecord" tabindex="-1">OnModifyRecord <a class="header-anchor" href="#onmodifyrecord" aria-label="Permalink to “OnModifyRecord”">​</a></h3><p>The <code>OnModifyRecord</code> trigger executes before an existing record is modified in the table.</p><p>It allows you to perform checks before accepting modifications.</p><p><strong>Example:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trigger OnModifyRecord(): Boolean</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    if Rec.&quot;Unit Price&quot; &lt; 0 then</span></span>
<span class="line"><span>        Error(&#39;Unit Price cannot be negative.&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    exit(true);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Here, Business Central checks whether the product&#39;s unit price is negative before allowing the modification.</p><p>The Boolean return value determines whether the modification is allowed.</p><table tabindex="0"><thead><tr><th>Return value</th><th>Meaning</th></tr></thead><tbody><tr><td><code>true</code></td><td>Allow the modification.</td></tr><tr><td><code>false</code></td><td>Cancel the modification.</td></tr></tbody></table><p><strong>When to use it:</strong> When you need to execute page-specific validation or checks before modifying a record.</p><h3 id="ondeleterecord" tabindex="-1">OnDeleteRecord <a class="header-anchor" href="#ondeleterecord" aria-label="Permalink to “OnDeleteRecord”">​</a></h3><p>The <code>OnDeleteRecord</code> trigger executes before a record is deleted from the table.</p><p>It allows you to perform additional checks before allowing the deletion.</p><p><strong>Example:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trigger OnDeleteRecord(): Boolean</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    if Rec.Inventory &gt; 0 then</span></span>
<span class="line"><span>        Error(&#39;Cannot delete a product with available inventory.&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    exit(true);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Here, Business Central checks whether the product has available inventory before allowing its deletion.</p><p>The Boolean return value determines whether deletion is allowed.</p><table tabindex="0"><thead><tr><th>Return value</th><th>Meaning</th></tr></thead><tbody><tr><td><code>true</code></td><td>Allow deletion.</td></tr><tr><td><code>false</code></td><td>Cancel deletion.</td></tr></tbody></table><p><strong>When to use it:</strong> When you need to enforce page-specific restrictions before a record is deleted.</p><h3 id="onvalidate-page-field" tabindex="-1">OnValidate (Page Field) <a class="header-anchor" href="#onvalidate-page-field" aria-label="Permalink to “OnValidate (Page Field)”">​</a></h3><p>So far, we&#39;ve looked at triggers associated with the page itself.</p><p>However, individual page fields can also have triggers.</p><p>One important example is the <code>OnValidate</code> trigger.</p><p>It executes when a user changes a field&#39;s value and the field is validated.</p><p><strong>Example:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>field(&quot;Unit Price&quot;; Rec.&quot;Unit Price&quot;)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    ApplicationArea = All;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    trigger OnValidate()</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        if Rec.&quot;Unit Price&quot; &lt; 0 then</span></span>
<span class="line"><span>            Error(&#39;Unit Price cannot be negative.&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here, whenever a user changes the Unit Price field, Business Central checks whether the entered value is negative.</p><p>If it is, an error is displayed.</p><p><strong>Important distinction:</strong></p><p>There are two places where you can define an <code>OnValidate</code> trigger:</p><ol><li><strong>Table field OnValidate:</strong> Defined on a table field. It implements validation logic associated with that field, regardless of which page is used to modify it.</li><li><strong>Page field OnValidate:</strong> Defined on a page field control. It implements validation logic specific to that page control.</li></ol><p>Generally, business rules that must apply regardless of where data is modified should be implemented at the table level.</p><p>We&#39;ll explore table triggers in a separate topic.</p><h2 id="understanding-page-trigger-execution" tabindex="-1">Understanding Page Trigger Execution <a class="header-anchor" href="#understanding-page-trigger-execution" aria-label="Permalink to “Understanding Page Trigger Execution”">​</a></h2><p>It&#39;s useful to understand the general order in which some of these triggers execute.</p><p>When a page is opened, the general sequence is:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Page Initialization</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>    OnInit</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>   OnOpenPage</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span> Records Retrieved</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span> OnAfterGetRecord</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>OnAfterGetCurrRecord</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span> Page Interaction</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>  OnQueryClosePage</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>   OnClosePage</span></span></code></pre></div><p>This is an illustrative overview, not a guaranteed complete execution sequence for every page.</p><p>For example, record retrieval triggers can execute multiple times as users navigate through a page or as Business Central loads additional records.</p><p>Also, <code>OnClosePage</code> only executes in its supported modal-page scenario.</p><h2 id="page-triggers-vs-table-triggers" tabindex="-1">Page Triggers vs Table Triggers <a class="header-anchor" href="#page-triggers-vs-table-triggers" aria-label="Permalink to “Page Triggers vs Table Triggers”">​</a></h2><p>This is an important distinction to understand as you continue learning AL.</p><p>Although both page triggers and table triggers execute AL code automatically, they serve different purposes.</p><table tabindex="0"><thead><tr><th>Page Triggers</th><th>Table Triggers</th></tr></thead><tbody><tr><td>Associated with page objects.</td><td>Associated with table objects.</td></tr><tr><td>Handle page lifecycle and user interactions.</td><td>Handle record and field operations.</td></tr><tr><td>Can execute when a page opens or closes.</td><td>Execute when records are inserted, modified, or deleted.</td></tr><tr><td>Can implement page-specific validation.</td><td>Can implement business rules that apply across different pages and operations.</td></tr></tbody></table><p>For example, suppose we want to prevent users from entering a negative product price.</p><p>If we implement the validation only in a page&#39;s <code>OnValidate</code> trigger, another process that modifies the table directly might bypass that page-specific validation.</p><p>If the rule is implemented in the table field&#39;s <code>OnValidate</code> trigger, it can apply wherever that field is validated.</p><p><strong>General rule:</strong> Put business rules at the table level when they must apply consistently across the application. Use page triggers for behavior specific to the user interface.</p><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to “Key Takeaways”">​</a></h2><ul><li>Page triggers are predefined execution points invoked automatically by Business Central.</li><li><code>OnInit</code> initializes page variables.</li><li><code>OnOpenPage</code> executes when a page opens.</li><li><code>OnClosePage</code> executes when a supported modal page closes.</li><li><code>OnQueryClosePage</code> allows you to control whether a page can close.</li><li><code>OnAfterGetRecord</code> executes when records are retrieved.</li><li><code>OnAfterGetCurrRecord</code> executes after the current record is retrieved.</li><li><code>OnNewRecord</code> initializes a new record before insertion.</li><li><code>OnInsertRecord</code>, <code>OnModifyRecord</code>, and <code>OnDeleteRecord</code> allow you to control record operations through a page.</li><li><code>OnValidate</code> can be defined on individual page fields.</li><li>Page triggers should not replace table-level business validation.</li></ul><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ol><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/triggers-auto/page/devenv-oninit-page-trigger" target="_blank" rel="noreferrer">Microsoft Learn – OnInit Trigger</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/triggers-auto/page/devenv-onopenpage-page-trigger" target="_blank" rel="noreferrer">Microsoft Learn – OnOpenPage Trigger</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/triggers-auto/page/devenv-onaftergetrecord-page-trigger" target="_blank" rel="noreferrer">Microsoft Learn – OnAfterGetRecord Trigger</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/triggers-auto/page/devenv-onnewrecord-page-trigger" target="_blank" rel="noreferrer">Microsoft Learn – OnNewRecord Trigger</a></li></ol><hr><h2 id="practical-exercise" tabindex="-1">Practical Exercise <a class="header-anchor" href="#practical-exercise" aria-label="Permalink to “Practical Exercise”">​</a></h2><p>Let&#39;s use your existing <code>ProductCard</code> page.</p><p>Implement the following:</p><ol><li><strong>OnOpenPage:</strong> Display a message welcoming the user to the Product Card.</li><li><strong>OnNewRecord:</strong> Initialize the Unit Price and Inventory fields to zero.</li><li><strong>OnAfterGetCurrRecord:</strong> Display the name of the currently selected product.</li><li><strong>OnModifyRecord:</strong> Prevent users from saving a product with a negative Unit Price.</li><li><strong>OnDeleteRecord:</strong> Prevent users from deleting products whose Inventory is greater than zero.</li></ol><p>Publish your extension and test each trigger.</p><p><strong>One challenge:</strong> Try creating a new product and observe when <code>OnNewRecord</code> executes relative to <code>OnInsertRecord</code>.</p>`,142)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};